struct DependencyTrap {
    // Initialization occurs in declaration order (top-down).
    // Accessing 'm1' here results in UB: 'm1' is uninitialized.
    int m2 = m1 + 10; // UB Access

    // m1 is initialized second.
    int m1 = 42;

    // Correcting the order:
    // int m1 = 42;
    // int m2 = m1 + 10;
};

// Ctor initializer list does not change this order.
struct Safe {
    int m1 = 42;
    int m2;
    Safe() : m2(m1 + 10) {}
};
